import asyncio
from h import *
async def menu(pg, x, y):
    await pg.mouse.click(x, y, button='right'); await pg.wait_for_timeout(250)
async def labels(pg): return await pg.evaluate("[...document.querySelectorAll('.ctx button')].map(b=>b.textContent.trim())")
async def pick(pg, txt):
    await pg.locator('.ctx button', has_text=txt).first.click(); await pg.wait_for_timeout(300)
async def main():
    async with Env() as e:
        pg = await e.page(w=1280, h=900); await pg.wait_for_timeout(1200)
        await pg.evaluate("""(()=>{const L=MSA.state.learning;L.videos=[1,2].map(i=>({id:'lv'+i,folder:null,url:'https://example.com/'+i,title:'درس '+i,note:'',created:Date.now()}));L.folders=[{id:'lf1',parent:null,name:'فولدر أ',color:'#4f8cff',created:Date.now()}];MSA.state.ui.ltab='videos';MSA.state.ui.learnFolder=null;MSA.save();MSA.go('learn')})()""")
        await pg.wait_for_timeout(700)
        vb = await pg.evaluate("(()=>{const r=document.querySelector('#view').getBoundingClientRect();return {x:r.x,y:r.y,w:r.width,h:r.height}})()")
        # empty area far below content
        await menu(pg, vb['x']+vb['w']/2, vb['y']+vb['h']-10)
        L = await labels(pg); print(L)
        ok('empty-area menu (below content) opens', len(L) >= 4, L)
        ok('has New folder / Add link / Select all / Refresh', all(any(k in x for x in L) for k in ['مجلد','لينك','تحديد الكل','تحديث']) or all(any(k in x for x in L) for k in ['folder','link','Select all','Refresh']), L)
        await pick(pg, 'لينك' if any('لينك' in x for x in L) else 'link'); await pg.wait_for_timeout(300)
        ok('Add link dialog opens from the menu', await pg.locator('.overlay').count() == 1)
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
        await menu(pg, vb['x']+vb['w']-6, vb['y']+300)
        await pick(pg, 'مجلد' if any('مجلد' in x for x in await labels(pg)) else 'folder')
        await pg.wait_for_selector('#askIn'); await pg.fill('#askIn', 'فولدر جديد'); await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(400)
        ok('New folder created from the menu', await pg.evaluate("MSA.state.learning.folders.some(f=>f.name==='فولدر جديد')"))
        # select all via menu
        await menu(pg, vb['x']+6, vb['y']+vb['h']-6); await pick(pg, 'تحديد الكل')
        ok('Select all picks every folder and video', await pg.evaluate("document.querySelectorAll('.is-sel').length===4"), await pg.evaluate("document.querySelectorAll('.is-sel').length"))
        await menu(pg, vb['x']+vb['w']/2, vb['y']+vb['h']-10); await pick(pg, 'إلغاء التحديد')
        ok('Clear selection from the menu', await pg.evaluate("document.querySelectorAll('.is-sel').length===0"))
        # item menu still has copy/cut/rename/delete/colour; copy + paste into folder
        r = await pg.evaluate("(()=>{const e=document.querySelector('.vcard');const r=e.getBoundingClientRect();return [r.x+r.width/2,r.y+r.height/2]})()")
        await menu(pg, r[0], r[1]); L = await labels(pg)
        ok('item menu: rename / copy / cut / colour / delete', all(any(k in x for x in L) for k in ['تسمية','نسخ','قص','تلوين','حذف']), L)
        await pick(pg, 'نسخ')
        await menu(pg, vb['x']+vb['w']/2, vb['y']+vb['h']-10)
        ok('Paste appears in the empty-area menu after copy', any('لصق' in x or 'Paste' in x for x in await labels(pg)), await labels(pg))
        n0 = await pg.evaluate("MSA.state.learning.videos.length"); await pick(pg, 'لصق'); await pg.wait_for_timeout(300)
        ok('paste adds a copy of the video', await pg.evaluate("MSA.state.learning.videos.length")==n0+1)
        # delete a folder via item menu (confirm)
        f = await pg.evaluate("(()=>{const e=document.querySelector('.fold[data-kind=f]');const r=e.getBoundingClientRect();return [r.x+r.width/2,r.y+r.height/2]})()")
        nf = await pg.evaluate("MSA.state.learning.folders.length")
        await menu(pg, f[0], f[1]); await pick(pg, 'حذف'); await pg.wait_for_timeout(300); await pg.evaluate(CONFJS); await pg.wait_for_timeout(400)
        ok('delete folder from the item menu', await pg.evaluate("MSA.state.learning.folders.length")==nf-1)
        # inside a folder, menu still works
        await pg.evaluate("MSA.state.ui.learnFolder=MSA.state.learning.folders[0].id;MSA.save();MSA.rerender()"); await pg.wait_for_timeout(400)
        await menu(pg, vb['x']+vb['w']/2, vb['y']+vb['h']-10)
        ok('menu also works inside a folder', len(await labels(pg)) >= 4)
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(100)
        # search input keeps the native menu (no custom menu on inputs)
        await pg.evaluate("MSA.state.ui.learnFolder=null;MSA.rerender()"); await pg.wait_for_timeout(300)
        if await pg.locator('#lq').count():
            await pg.mouse.click(5,5); await pg.locator('#lq').click(button='right'); await pg.wait_for_timeout(200)
            ok('right-click on the search box does not open the custom menu', await pg.locator('.ctx').count() == 0)
        # move to… (video into a folder, then back to top level; a folder cannot be moved into itself)
        await pg.evaluate("MSA.state.ui.learnFolder=null;MSA.rerender()"); await pg.wait_for_timeout(300)
        fid = await pg.evaluate("MSA.state.learning.folders[0].id"); fname = await pg.evaluate("MSA.state.learning.folders[0].name")
        r = await pg.evaluate("(()=>{const e=document.querySelector('.vcard');const r=e.getBoundingClientRect();return [r.x+r.width/2,r.y+r.height/2,e.dataset.id]})()")
        await menu(pg, r[0], r[1]); ok('item menu has Move to…', any('نقل' in x for x in await labels(pg)))
        await pick(pg, 'نقل'); await pg.wait_for_selector('[data-mv]')
        await pg.locator('[data-mv="%s"]' % fid).click(); await pg.wait_for_timeout(400)
        ok('video moved into the folder', await pg.evaluate("MSA.state.learning.videos.find(v=>v.id==='%s').folder==='%s'" % (r[2], fid)))
        f = await pg.evaluate("(()=>{const e=document.querySelector('.fold[data-kind=f]');const r=e.getBoundingClientRect();return [r.x+r.width/2,r.y+r.height/2]})()")
        await menu(pg, f[0], f[1]); await pick(pg, 'نقل'); await pg.wait_for_selector('[data-mv]')
        ok('a folder is not offered as its own destination', await pg.locator('[data-mv="%s"]' % fid).count() == 0)
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
        ok('no page errors', not pg.errs, pg.errs[:3])
asyncio.run(main()); summary()
